const fs = require('fs');
const path = require('path');

// Brand assets from the canvas "G" tile (UX, 26 Oct 2026), generated by
// scripts/brand/make_brand_assets.py. Pins the sizes, the alpha rules and the
// config wiring, so the Expo template assets can't come back.
const ROOT = path.join(__dirname, '..', '..');
const ASSETS = path.join(ROOT, 'assets');

// Width, height and whether the PNG has an alpha channel (IHDR colour type).
function png(name) {
  const b = fs.readFileSync(path.join(ASSETS, name));
  expect(b.subarray(1, 4).toString('latin1')).toBe('PNG');
  const colourType = b[25];
  return { width: b.readUInt32BE(16), height: b.readUInt32BE(20), alpha: colourType === 4 || colourType === 6 };
}

describe('brand assets (v2)', () => {
  const config = fs.readFileSync(path.join(ROOT, 'app.config.js'), 'utf8');

  it('iOS app icon: 1024² and opaque (App Store rule)', () => {
    expect(png('icon.png')).toEqual({ width: 1024, height: 1024, alpha: false });
    expect(config).toContain("icon: './assets/icon.png'");
  });

  it('Android adaptive icon: the 432 px G layers on a solid gold background', () => {
    expect(png('android-icon-foreground.png')).toEqual({ width: 432, height: 432, alpha: true });
    expect(png('android-icon-monochrome.png')).toEqual({ width: 432, height: 432, alpha: true });
    expect(config).toContain("backgroundColor: '#FFC21A',\n        foregroundImage: './assets/android-icon-foreground.png'");
    expect(config).not.toContain('android-icon-background.png');
    expect(fs.existsSync(path.join(ASSETS, 'android-icon-background.png'))).toBe(false);
  });

  it('notification icon: 96 px white G on transparent, tinted gold', () => {
    expect(png('notification-icon.png')).toEqual({ width: 96, height: 96, alpha: true });
    expect(config).toContain("['expo-notifications', { icon: './assets/notification-icon.png', color: '#FFC21A' }]");
  });

  it('splash: the 52 pt G tile at 3x (156 px)', () => {
    expect(png('splash-icon.png')).toEqual({ width: 156, height: 156, alpha: true });
    expect(config).toContain("image: './assets/splash-icon.png', imageWidth: 52");
  });

  it('SVG sources hold outlines only, no <text> (the glyph is converted from Geist-Bold)', () => {
    const sources = fs.readdirSync(path.join(ASSETS, 'brand')).filter((name) => name.endsWith('.svg'));
    expect(sources.sort()).toEqual(
      ['android-icon-foreground', 'android-icon-monochrome', 'app-icon', 'notification-icon', 'splash-tile'].map((name) => `${name}.svg`)
    );
    sources.forEach((name) => {
      const svg = fs.readFileSync(path.join(ASSETS, 'brand', name), 'utf8');
      expect(svg).not.toMatch(/<text/);
      expect(svg).toMatch(/<path d="M/);
    });
  });
});
